/* Message input */
.message-input {
    padding: 0.75rem 1.25rem;
    border-top: 1px solid #e0e0e0;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    background: white;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
