@using sv_f113d9bc6b804d1aacab242065064dfa.Services
@namespace sv_f113d9bc6b804d1aacab242065064dfa.Components.Pages.Chat

<div class="message-area">
    <div class="message-area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
        @if (_isLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }

        @foreach (var message in Messages)
        {
            var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
            <ChatMessage Message="message"
                         IsThreadStarter="@(threadInfo is not null)"
                         ReplyCount="@(threadInfo?.ReplyCount ?? 0)"
                         OnOpenThread="OnOpenThread"
                         OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")" ButtonLabel="Send" OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private bool _isLoadingMore;

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages
        // The actual scroll position check is handled via JS interop in a real app,
        // but we expose the callback for the parent to handle pagination
        if (!_isLoadingMore)
        {
            _isLoadingMore = true;
            await OnLoadMore.InvokeAsync();
            _isLoadingMore = false;
        }
    }
}

